function smallestNumber(n) {
  if (n === 1) {
    return '1';
  }
  const digits = [];
  let rest = n;
  for (let digit = 9; digit >= 2; digit--) {
    while (rest % digit === 0) {
      digits.push(digit);
      rest /= digit;
    }
  }
  if (rest !== 1) {
    return '-1';
  }
  return digits.reverse().join('');
}

