function smallestNumber(n) {
  // Try every first digit recursively and keep the shortest, then smallest, sorted digit string.
  const memo = new Map();
  const better = (a, b) => b === null || a.length < b.length || (a.length === b.length && a < b);
  const best = value => {
    if (value === 1) return '';
    if (memo.has(value)) return memo.get(value);
    let found = null;
    for (let d = 2; d <= 9; d++) {
      if (value % d !== 0) continue;
      const tail = best(value / d);
      if (tail === null) continue;
      const candidate = (String(d) + tail).split('').sort().join('');
      if (better(candidate, found)) found = candidate;
    }
    memo.set(value, found);
    return found;
  };
  if (n === 1) return '1';
  const answer = best(n);
  return answer === null ? '-1' : answer;
}

