function generate(rand, size) {
  const limit = size === 'large' ? 1e15 : 5000;
  const mode = rand();
  if (size === 'small' && mode < 0.3) return [1 + Math.floor(rand() * 300)];
  if (size === 'large' && mode < 0.15) return [1 + Math.floor(rand() * limit)];
  // Multiply random digits; sometimes add a prime factor that no digit can supply.
  const blockers = [11, 13, 17, 19, 23, 97];
  let n = 1;
  if (rand() < 0.3) n = blockers[Math.floor(rand() * blockers.length)];
  for (;;) {
    const digit = 2 + Math.floor(rand() * 8);
    if (n * digit > limit) break;
    n *= digit;
    if (size === 'small' && rand() < 0.25) break;
  }
  return [n];
}
